$opt = function (array $rows, $sel) { $o = ''; foreach ($rows as $r) { $o .= '<option value="' . (int) $r->id . '"' . ((int) $r->id === (int) $sel ? ' selected' : '') . '>' . h($r->label) . '</option>'; } return $o; };
?>
<form data-sl-form action="ajax/sl/pickup_ajax.php" method="post" id="sp-form">
<input type="hidden" name="op" value="create"><input type="hidden" name="window" id="sp-window" value="<?= h($d['windows'][1]) ?>"><input type="hidden" name="kind" id="sp-kind" value="collect"><input type="hidden" name="packages" id="sp-pk" value="[]">
<div class="row g8 mut sm"><a href="<?= sl_route('Pickups') ?>">Pickups</a><i class="ic ic-sm i-right" aria-hidden="true"></i><span style="color:var(--ink)">Schedule</span></div>
<div class="sl-head"><div><h1 class="sl-title"><?= $d['isClient'] ? 'Request a pickup' : 'Schedule a pickup' ?></h1><p class="sl-lede">Collect parcels from a customer or deliver to their door</p></div><div class="row g8 wrap"><a class="sl-btn ghost" href="<?= sl_route('Pickups') ?>">Cancel</a><button type="submit" class="sl-btn"><i class="ic ic-sm i-check" aria-hidden="true"></i>Book pickup</button></div></div>
<div class="split"><div class="a col g16"><section class="sl-card col g16"><div class="sl-ch" style="margin:0"><h2 class="sl-ct">Who and where</h2></div>
<div class="sl-field"><span class="sl-lab">Type</span><div class="sl-seg boxed" id="sp-kinds"><button type="button" class="on" data-k="collect">Collect from customer</button><button type="button" data-k="deliver">Deliver to customer</button></div></div>
<?php if ($d['isClient']): ?><div class="sl-field"><span class="sl-lab">Customer</span><div class="sl-sel"><span><?= h(trim($d['me']->fname . ' ' . $d['me']->lname)) ?><?= $d['me']->locker ? ' · ' . h($d['me']->locker) : '' ?></span></div></div>
<?php else: ?><label class="sl-field"><span class="sl-lab">Customer</span><span class="sl-sel native"><select name="sender_id" id="sp-cust" required><option value="">Select customer</option><?php foreach ($d['customers'] as $c): ?><option value="<?= (int) $c->id ?>" data-phone="<?= h($c->phone) ?>"><?= h(trim($c->fname . ' ' . $c->lname)) ?><?= $c->locker ? ' · ' . h($c->locker) : '' ?></option><?php endforeach; ?></select><i class="ic ic-sm i-down" aria-hidden="true"></i></span></label><?php endif; ?>
<label class="sl-field"><span class="sl-lab">Address</span><span class="sl-sel native"><select name="sender_address_id" id="sp-addr" required><?php if ($d['isClient']): ?><?php foreach ($d['addresses'] as $a): ?><option value="<?= (int) $a['id'] ?>"><?= h($a['label']) ?></option><?php endforeach; ?><?php if (!$d['addresses']): ?><option value="">Add an address to your account first</option><?php endif; ?><?php else: ?><option value="">Pick a customer first</option><?php endif; ?></select><i class="ic ic-sm i-down" aria-hidden="true"></i></span></label>
<label class="sl-field"><span class="sl-lab">Contact phone</span><input class="sl-in" name="phone" id="sp-phone" value="<?= h($d['me']->phone ?? '') ?>" placeholder="+233 …"></label></section>
<section class="sl-card col g16"><div class="sl-ch" style="margin:0"><h2 class="sl-ct">When</h2></div><div class="grid cols2" style="gap:12px"><label class="sl-field"><span class="sl-lab">Date</span><input type="date" class="sl-in" name="order_date" value="<?= h($d['today']) ?>" min="<?= h(date('Y-m-d')) ?>" required></label><label class="sl-field"><span class="sl-lab">Repeat</span><span class="sl-sel native"><select name="repeat"><option value="">Does not repeat</option><option value="weekly">Every week (4 pickups)</option></select><i class="ic ic-sm i-down" aria-hidden="true"></i></span></label></div>
<div class="row g6 wrap" id="sp-wins"><?php foreach ($d['windows'] as $i => $w): ?><button type="button" class="np-chip" data-w="<?= h($w) ?>" style="padding-right:12px;<?= $i === 1 ? 'background:var(--ink);color:var(--inverse)' : '' ?>"><?= h($w) ?></button><?php endforeach; ?></div></section>
<section class="sl-card col g16"><div class="sl-ch" style="margin:0"><h2 class="sl-ct">Parcels</h2><button type="button" class="sl-btn ghost sm" id="sp-add"><i class="ic ic-sm i-plus" aria-hidden="true"></i>Add parcel</button></div><div class="col g8" id="sp-parcels"></div>
<template id="sp-parcel"><div class="row g8 wrap"><input class="sl-in sm grow" data-k="description" placeholder="What is it? e.g. 2 boxes of clothes" style="min-width:220px"><input class="sl-in sm mono" data-k="qty" type="number" min="1" value="1" style="width:70px" aria-label="Quantity"><input class="sl-in sm mono" data-k="weight" type="number" min="0" step="0.1" value="1" style="width:90px" aria-label="Weight"><button type="button" class="sl-ib sm sp-del" aria-label="Remove"><i class="ic i-trash" aria-hidden="true"></i></button></div></template>
<label class="sl-field"><span class="sl-lab">Notes for driver</span><textarea class="np-ta" name="notes" style="min-height:80px" placeholder="Call on arrival. Gate code 4471."></textarea></label></section></div>
<aside class="b col g16"><?php if (!$d['isClient']): ?><section class="sl-card col g16"><div class="sl-ch" style="margin:0"><h2 class="sl-ct">Driver</h2></div><label class="sl-field"><span class="sl-lab">Assign</span><span class="sl-sel native"><select name="driver_id"><option value="0">Assign later</option><?php foreach ($d['drivers'] as $dr): ?><option value="<?= (int) $dr['id'] ?>"><?= h($dr['label']) ?></option><?php endforeach; ?></select><i class="ic ic-sm i-down" aria-hidden="true"></i></span></label><a class="sm fw5" href="<?= sl_route('Drivers') ?>">See all drivers →</a></section>
<section class="sl-card col g12"><h2 class="sl-ct">Booking</h2><label class="sl-field"><span class="sl-lab">Agency</span><span class="sl-sel native"><select name="agency"><?= $opt($L['agencies'], $def['agency']) ?></select><i class="ic ic-sm i-down" aria-hidden="true"></i></span></label><label class="sl-field"><span class="sl-lab">Office</span><span class="sl-sel native"><select name="origin_off"><?= $opt($L['offices'], $def['origin_off']) ?></select><i class="ic ic-sm i-down" aria-hidden="true"></i></span></label><label class="sl-field"><span class="sl-lab">Payment</span><span class="sl-sel native"><select name="order_payment_method"><?= $opt($L['paymethods'], 0) ?></select><i class="ic ic-sm i-down" aria-hidden="true"></i></span></label></section><?php endif; ?>
<section class="sl-card col g16"><div class="sl-ch" style="margin:0"><h2 class="sl-ct">Customer is told</h2></div><div class="row g10"><span class="sl-toggle on" role="switch" aria-checked="true" aria-label="WhatsApp"><input type="hidden" name="notify_whatsapp" value="1"></span><span class="col"><span>WhatsApp with time window</span></span></div><div class="row g10"><span class="sl-toggle on" role="switch" aria-checked="true" data-static aria-label="Pickup code"></span><span class="col"><span>Pickup code</span><span class="mut sm">Sent with the ready message when the parcels can be collected</span></span></div></section></aside></div>
</form>
<script>
(function () {
  var box = document.getElementById('sp-parcels'), tpl = document.getElementById('sp-parcel');
  function sync() { var l = []; box.querySelectorAll('.row').forEach(function (r) { var g = function (k) { return r.querySelector('[data-k=' + k + ']').value; }; if (g('description').trim()) l.push({ description: g('description'), qty: +g('qty') || 1, weight: +g('weight') || 0, length: 0, width: 0, height: 0, declared_value: 0, fixed_value: 0 }); }); document.getElementById('sp-pk').value = JSON.stringify(l); }
  function add() { box.appendChild(tpl.content.cloneNode(true)); }
  document.getElementById('sp-add').addEventListener('click', add); add();
  box.addEventListener('click', function (e) { if (e.target.closest('.sp-del') && box.children.length > 1) { e.target.closest('.row').remove(); sync(); } });
  document.getElementById('sp-form').addEventListener('input', sync);
  document.getElementById('sp-wins').addEventListener('click', function (e) { var b = e.target.closest('[data-w]'); if (!b) return; this.querySelectorAll('[data-w]').forEach(function (x) { x.style.background = ''; x.style.color = ''; }); b.style.background = 'var(--ink)'; b.style.color = 'var(--inverse)'; document.getElementById('sp-window').value = b.getAttribute('data-w'); });
  document.getElementById('sp-kinds').addEventListener('click', function (e) { var b = e.target.closest('[data-k]'); if (!b) return; this.querySelectorAll('button').forEach(function (x) { x.classList.toggle('on', x === b); }); document.getElementById('sp-kind').value = b.getAttribute('data-k'); });
  var cust = document.getElementById('sp-cust'), addr = document.getElementById('sp-addr');
  if (cust) cust.addEventListener('change', function () {
    var o = cust.options[cust.selectedIndex]; document.getElementById('sp-phone').value = o ? (o.getAttribute('data-phone') || '') : '';
    addr.innerHTML = '<option value="">Loading…</option>';
    SL.get('ajax/sl/pickup_ajax.php', { op: 'addresses', id: cust.value }).then(function (j) { addr.innerHTML = ''; (j.addresses || []).forEach(function (a) { var x = document.createElement('option'); x.value = a.id; x.textContent = a.label; addr.appendChild(x); }); if (!addr.options.length) addr.innerHTML = '<option value="">No address on file</option>'; });
  });
  document.getElementById('sp-form').addEventListener('submit', sync, true);
})();
</script>
